-- Random settings limits: group_by_two_level_threshold=(100000, None); group_by_two_level_threshold_bytes=(50000000, None); max_bytes_before_external_group_by=(0, 0); max_bytes_ratio_before_external_group_by=(0, 0)
-- GROUP BY of one 4- or 8-byte key with only count() counts runs of equal keys once each; every cell compares it with the same GROUP BY that also computes min(), which counts row by row.

-- Run shapes, one block per query.
WITH src AS (SELECT number, toUInt32(b) AS k FROM (SELECT number, intDiv(number, 4) % 1000 AS b FROM numbers(16003))) SELECT 'UInt32 runs4', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 65536;
WITH src AS (SELECT number, toUInt32(b) AS k FROM (SELECT number, intDiv(number * 2, 3) % 1000 AS b FROM numbers(16003))) SELECT 'UInt32 alt12', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 65536;
WITH src AS (SELECT number, toUInt32(b) AS k FROM (SELECT number, if(intDiv(number, 64) % 2 = 0, number, intDiv(number, 4)) % 1000 AS b FROM numbers(16003))) SELECT 'UInt32 mix64', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 65536;
WITH src AS (SELECT number, toUInt32(b) AS k FROM (SELECT number, if(number % 16384 < 9000, number, intDiv(number, 4)) % 1000 AS b FROM numbers(50000))) SELECT 'UInt32 noruns_then_runs', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 65536;
