-- Key types; float keys include nan, -nan, -0., 0., inf and -inf inside runs.
WITH src AS (SELECT number, toInt32(toInt64(b) - 500) AS k FROM (SELECT number, intDiv(number, 4) % 1000 AS b FROM numbers(16003))) SELECT 'Int32 runs4', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 65536;
