WITH src AS (SELECT number, toFloat32(multiIf(b % 8 = 0, nan, b % 8 = 1, -nan, b % 8 = 2, -0., b % 8 = 3, 0., b % 8 = 4, inf, b % 8 = 5, -inf, b / 3)) AS k FROM (SELECT number, intDiv(number, 4) % 1000 AS b FROM numbers(16003))) SELECT 'Float32 runs4', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 65536;
