WITH src AS (SELECT number, toUInt32(b) AS k FROM (SELECT number, intDiv(number, 64) % 1000 AS b FROM numbers(16003))) SELECT 'UInt32 r64 max_block_size=1000', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 1000;

-- Blocks that start with runs and then lose them, and the reverse.
WITH src AS (SELECT number, toUInt64(b) AS k FROM (SELECT number, if(number % 4096 < 1024, cityHash64(intDiv(number, 4)) % 1000, 1000 + cityHash64(number) % 1000) AS b FROM numbers(16384))) SELECT 'UInt64 runs_then_noruns', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 4096;
WITH src AS (SELECT number, toUInt64(b) AS k FROM (SELECT number, if(number % 4096 < 1024, cityHash64(intDiv(number, 4)) % 1000, 1000 + cityHash64(intDiv(number, 3) * 2 + (number % 3 >= 1)) % 1000) AS b FROM numbers(16384))) SELECT 'UInt64 runs_then_runs12', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 4096;
WITH src AS (SELECT number, toUInt64(b) AS k FROM (SELECT number, if(number % 4096 < 1024, cityHash64(number) % 1000, 1000 + cityHash64(intDiv(number, 4)) % 1000) AS b FROM numbers(16384))) SELECT 'UInt64 noruns_then_runs4', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 4096;

-- The first 64 rows of each block hold exactly 40, 41, 48 or 49 runs, and the rest runs of 4.
WITH src AS (SELECT number, toUInt64(b) AS k FROM (SELECT number, if(number % 4096 < 64, least(number % 4096, 39), 100 + intDiv(number % 4096, 4)) AS b FROM numbers(16384))) SELECT 'UInt64 first_group_40_runs', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 4096;
WITH src AS (SELECT number, toUInt64(b) AS k FROM (SELECT number, if(number % 4096 < 64, least(number % 4096, 40), 100 + intDiv(number % 4096, 4)) AS b FROM numbers(16384))) SELECT 'UInt64 first_group_41_runs', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 4096;
WITH src AS (SELECT number, toUInt64(b) AS k FROM (SELECT number, if(number % 4096 < 64, least(number % 4096, 47), 100 + intDiv(number % 4096, 4)) AS b FROM numbers(16384))) SELECT 'UInt64 first_group_48_runs', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 4096;
WITH src AS (SELECT number, toUInt64(b) AS k FROM (SELECT number, if(number % 4096 < 64, least(number % 4096, 48), 100 + intDiv(number % 4096, 4)) AS b FROM numbers(16384))) SELECT 'UInt64 first_group_49_runs', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 4096;

-- A limit on the number of keys stops adding keys after the first block.
WITH src AS (SELECT number, toUInt64(b) + 0xFFFFFFFF00000000 AS k FROM (SELECT number, intDiv(number, 4) % 1000 AS b FROM numbers(16003))) SELECT 'UInt64 runs4 max_rows_to_group_by', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 1024, max_rows_to_group_by = 100, group_by_overflow_mode = 'any';
SELECT k, count() FROM (SELECT toUInt64(intDiv(number, 4) % 1000) AS k FROM numbers(16003)) GROUP BY k WITH TOTALS ORDER BY k LIMIT 3 SETTINGS max_threads = 1, max_block_size = 1024, max_rows_to_group_by = 100, group_by_overflow_mode = 'any';

-- A constant key.
WITH src AS (SELECT number, toUInt64(7) AS k FROM numbers(1000)) SELECT 'UInt64 constant key', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 1, max_block_size = 65536, optimize_group_by_constant_keys = 0;

-- Several threads, with and without the adaptive aggregator, and with tables frozen early.
WITH src AS (SELECT number, toUInt64(b) + 0xFFFFFFFF00000000 AS k FROM (SELECT number, intDiv(number, 4) % 1000 AS b FROM numbers_mt(1000000))) SELECT 'UInt64 runs4 max_threads=4 no_adaptive', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 4, max_block_size = 8192, enable_adaptive_aggregator = 0;
WITH src AS (SELECT number, toUInt64(b) + 0xFFFFFFFF00000000 AS k FROM (SELECT number, intDiv(number, 4) % 1000 AS b FROM numbers_mt(1000000))) SELECT 'UInt64 runs4 max_threads=4', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 4, max_block_size = 8192, enable_adaptive_aggregator = 1;
WITH src AS (SELECT number, toUInt64(b) + 0xFFFFFFFF00000000 AS k FROM (SELECT number, intDiv(number, 4) % 1000 AS b FROM numbers_mt(1000000))) SELECT 'UInt64 runs4 max_threads=4 frozen', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 4, max_block_size = 1024, enable_adaptive_aggregator = 1, adaptive_aggregator_freeze_threshold = 128;
WITH src AS (SELECT number, toUInt64(b) + 0xFFFFFFFF00000000 AS k FROM (SELECT number, intDiv(number * 2, 3) % 1000 AS b FROM numbers_mt(1000000))) SELECT 'UInt64 alt12 max_threads=4 frozen', (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k)) = (SELECT groupBitXor(cityHash64(k, c)), count(), sum(c) FROM (SELECT k, count() AS c FROM src GROUP BY k HAVING min(number) >= 0)) SETTINGS max_threads = 4, max_block_size = 1024, enable_adaptive_aggregator = 1, adaptive_aggregator_freeze_threshold = 128;
